const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define western Pacific Ocean region (tropical: -20 to 20° lat, 120-180° lon)
  const region = ee.Geometry.Polygon([[
    [120, -20], [180, -20], [180, 20], [120, 20], [120, -20]
  ]]);

  // 2. Use TRMM 3B43 monthly precipitation (mm/hr)
  const getAnnualRainfall = function(year) {
    const start = ee.Date.fromYMD(year, 1, 1);
    const end = start.advance(1, 'year');
    const col = ee.ImageCollection('TRMM/3B43V7')
      .filterDate(start, end)
      .filterBounds(region)
      .select('precipitation');

    const count = col.size();
    if (count.getInfo() === 0) return null;

    // Average monthly precipitation rate (mm/hr)
    const annualMean = col.mean();

    // Count valid pixels (no cloud mask needed for TRMM)
    const pixelCount = annualMean.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 25000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    return {
      mean: annualMean.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 25000,
        maxPixels: 1e9
      }).get('precipitation'),
      pixels: pixelCount,
      images: count.getInfo()
    };
  };

  // 3. Get data for both years
  const data1998 = getAnnualRainfall(1998);
  const data2009 = getAnnualRainfall(2009);

  // 4. Handle missing data cases
  if (!data1998 || !data2009) {
    console.log(`1998 Images: ${data1998 ? data1998.images : 0}`);
    console.log(`2009 Images: ${data2009 ? data2009.images : 0}`);
    console.log("<answer>C1</answer>");
    return;
  }

  const mean1998 = data1998.mean.getInfo();
  const mean2009 = data2009.mean.getInfo();
  const pixels1998 = data1998.pixels;
  const pixels2009 = data2009.pixels;

  // 5. Check for no valid pixels
  if (pixels1998 === 0 || pixels2009 === 0) {
    console.log(`1998 Pixels: ${pixels1998}, Rate: ${mean1998}`);
    console.log(`2009 Pixels: ${pixels2009}, Rate: ${mean2009}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Validate results
  if (mean1998 === null || mean2009 === null || 
      isNaN(mean1998) || isNaN(mean2009) ||
      mean1998 < 0 || mean2009 < 0 || 
      mean1998 > 10 || mean2009 > 10) { // Unreasonable rainfall rates
    console.log(`1998: ${mean1998}, 2009: ${mean2009}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare and output
  console.log(`1998: ${mean1998.toFixed(3)} mm/hr, ${data1998.images} months`);
  console.log(`2009: ${mean2009.toFixed(3)} mm/hr, ${data2009.images} months`);
  console.log(`Change: ${((mean2009 - mean1998) / mean1998 * 100).toFixed(1)}%`);

  if (mean2009 > mean1998) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
